#import <Metal/Metal.h>
#include "underwater_medium.hpp"
#include <cstdio>
#include <vector>
#include <chrono>
#include <thread>
int main() { @autoreleasepool {
 id<MTLDevice> device=MTLCreateSystemDefaultDevice(); id<MTLCommandQueue> queue=[device newCommandQueue];
 const int w=1280,h=800; auto d=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm width:w height:h mipmapped:NO]; d.storageMode=MTLStorageModeShared; d.usage=MTLTextureUsageShaderRead|MTLTextureUsageRenderTarget; id<MTLTexture> src=[device newTextureWithDescriptor:d],dst=[device newTextureWithDescriptor:d];
 std::vector<unsigned char> pixels(w*h*4);for(int i=0;i<w*h;i++){pixels[i*4]=180;pixels[i*4+1]=120;pixels[i*4+2]=200;pixels[i*4+3]=255;} [src replaceRegion:MTLRegionMake2D(0,0,w,h) mipmapLevel:0 withBytes:pixels.data() bytesPerRow:w*4];
 d.pixelFormat=MTLPixelFormatDepth32Float;d.storageMode=MTLStorageModePrivate;id<MTLTexture> depth=[device newTextureWithDescriptor:d];id<MTLCommandBuffer> init=[queue commandBuffer];auto pass=[MTLRenderPassDescriptor renderPassDescriptor];pass.depthAttachment.texture=depth;pass.depthAttachment.loadAction=MTLLoadActionClear;pass.depthAttachment.clearDepth=1;pass.depthAttachment.storeAction=MTLStoreActionStore;id<MTLRenderCommandEncoder> e=[init renderCommandEncoderWithDescriptor:pass];[e endEncoding];[init commit];[init waitUntilCompleted];
 storm_metal::UnderwaterMedium medium;storm_metal::UnderwaterUniforms u{matrix_identity_float4x4,matrix_identity_float4x4,{0,0,0,0},{0,0,float(w),float(h)}};
 auto start=std::chrono::steady_clock::now();medium.request(device,dst.pixelFormat);auto returned=std::chrono::steady_clock::now();
 while(!medium.ready(dst.pixelFormat) && std::chrono::steady_clock::now()-start<std::chrono::seconds(5)) std::this_thread::sleep_for(std::chrono::milliseconds(1));
 printf("request_ms %.3f ready_ms %.3f\n",std::chrono::duration<double,std::milli>(returned-start).count(),std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count());if(!medium.ready(dst.pixelFormat))return 2;
 for(float value: {0.01f,.4f,20.f}){u.parameters.x=value;auto cmd=[queue commandBuffer];if(!medium.encode(device,cmd,src,depth,dst,u))return 3;[cmd commit];[cmd waitUntilCompleted];if(cmd.status!=MTLCommandBufferStatusCompleted){fprintf(stderr,"%s\n",cmd.error.localizedDescription.UTF8String);return 4;}unsigned char v[4];[dst getBytes:v bytesPerRow:4 fromRegion:MTLRegionMake2D(w/2,h/2,1,1) mipmapLevel:0];printf("depth %.2f BGRA %u %u %u %u\n",value,v[0],v[1],v[2],v[3]);}
 u.inverseProjection.columns[2].z=100.f; u.parameters.x=20.f;
 for(float z: {.1f,.8f,1.f}) {auto clear=[queue commandBuffer];auto target=[MTLRenderPassDescriptor renderPassDescriptor];target.depthAttachment.texture=depth;target.depthAttachment.loadAction=MTLLoadActionClear;target.depthAttachment.clearDepth=z;target.depthAttachment.storeAction=MTLStoreActionStore;auto enc=[clear renderCommandEncoderWithDescriptor:target];[enc endEncoding];[clear commit];[clear waitUntilCompleted];auto cmd=[queue commandBuffer];if(!medium.encode(device,cmd,src,depth,dst,u))return 6;[cmd commit];[cmd waitUntilCompleted];unsigned char v[4];[dst getBytes:v bytesPerRow:4 fromRegion:MTLRegionMake2D(w/2,h/2,1,1) mipmapLevel:0];printf("scene depth %.1f BGRA %u %u %u %u\n",z,v[0],v[1],v[2],v[3]);}
 for(int mode=0;mode<2;mode++){double gpu=0,cpu=0;for(int i=0;i<36;i++){auto t=std::chrono::steady_clock::now();id<MTLCommandBuffer> cmd=[queue commandBuffer];id<MTLBlitCommandEncoder> blit=[cmd blitCommandEncoder];[blit copyFromTexture:src sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0,0,0) sourceSize:MTLSizeMake(w,h,1) toTexture:dst destinationSlice:0 destinationLevel:0 destinationOrigin:MTLOriginMake(0,0,0)];[blit endEncoding];if(mode){u.parameters.x=20;if(!medium.encode(device,cmd,src,depth,dst,u))return 5;}[cmd commit];[cmd waitUntilCompleted];if(i>=6){gpu+=(cmd.GPUEndTime-cmd.GPUStartTime)*1000;cpu+=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count();}}printf("%s GPU mean %.3f ms CPU+wait mean %.3f ms n=30\n",mode?"copy+medium":"copy",gpu/30,cpu/30);}
 return 0;}}
